class CliTests(unittest.TestCase):
    def run_cli(self, *argv, files=None):
        with tempfile.TemporaryDirectory() as d:
            for k, v in (files or {}).items():
                with open(os.path.join(d, k), 'w', encoding='utf-8', newline='') as fh:
                    fh.write(v)
            env = dict(os.environ, PYTHONPATH=os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
            p = subprocess.run([sys.executable, '-m', 'tabula'] + list(argv), cwd=d, env=env, capture_output=True, text=True)
            return p.returncode, p.stdout, p.stderr

    def test_commands(self):
        f = {'t.csv': 'name,qty\nax,3\nby,10\ncz,7\n'}
        for argv, rc, out in [(('show', 't.csv'), 0, 'name  qty\nax    3\nby    10\ncz    7\n'),
                              (('head', 't.csv', '1'), 0, 'name  qty\nax    3\n'),
                              (('--format', 'csv', 'cols', 't.csv'), 0, 'position,column\n1,name\n2,qty\n'),
                              (('apply', 't.csv', 'qty', 'add:1', 'mul:2', '--format=csv'), 0, 'name,qty\nax,8\nby,22\ncz,16\n'),
                              (('apply', 't.csv', 'name', 'upper', '--format', 'json'), 0, '[{"name": "AX", "qty": "3"}, {"name": "BY", "qty": "10"}, {"name": "CZ", "qty": "7"}]\n'),
                              (('show', 'missing.csv'), 1, ''), (('apply', 't.csv', 'nope', 'upper'), 1, ''),
                              (('apply', 't.csv', 'name', 'add:1'), 1, ''), (('bogus',), 2, ''), ((), 2, ''), (('show', '--wat', 't.csv'), 2, '')]:
class OptionTests(clihelp.CommandTest):
    def test_options_anywhere(self):
        f = {"t.csv": "a\n1\n"}
        for argv in (["--kind", "left", "show", "t.csv"], ["show", "t.csv", "--kind", "left"], ["--kind=inner", "show", "t.csv"],
                     ["show", "--keep=last", "t.csv"], ["--keep", "first", "--kind=left", "--format=csv", "show", "t.csv"],
                     ["show", "t.csv", "--format", "text", "--keep", "last"]):
            with self.subTest(argv):
                self.assertEqual(run(argv, f)[0], 0)
        self.ok(["--format=csv", "--keep", "last", "head", "t.csv", "1", "--kind=left"], f, "a\n1\n")

    def test_bad_options_are_usage_errors(self):
        f = {"t.csv": "a\n1\n"}
        for argv in (["--kind", "outer", "show", "t.csv"], ["show", "t.csv", "--kind=right"], ["--keep=middle", "show", "t.csv"],
                     ["show", "t.csv", "--keep", "FIRST"], ["--kind=", "show", "t.csv"], ["--keep", "show", "t.csv"],
                     ["show", "t.csv", "--kind"], ["show", "t.csv", "--keep"], ["--format=xml", "show", "t.csv"], ["--format"],
                     ["--formats=csv", "show", "t.csv"], ["--kinds", "left", "show", "t.csv"], ["show", "t.csv", "--wat"]):
            with self.subTest(argv):
                self.fails(argv, f, None, 2)
        self.fails(["--kind", "outer", "show", "t.csv"], f, "--kind must be one of inner, left, got 'outer'", 2)
        self.fails(["show", "--keep=x", "t.csv"], f, "--keep must be one of first, last, got 'x'", 2)
        self.fails(["--format=xml", "show", "t.csv"], f, "--format must be one of text, csv, json, got 'xml'", 2)
        self.fails(["--format"], f, "--format needs a value", 2)

